NAMES = ["Anna", "Ali", "Ece", "Mert", "Elif", "Baran", "Deniz", "Laura"]


def clean(text):
    return re.sub(r"\s+", " ", text.strip())


def seed_seen():
    seen = {}
    lessons = HERE.parents[2] / "Idiomas" / "cursos" / "tr" / "lessons"
    for path in sorted(lessons.glob("[0-9][0-9][0-9].json")):
        if int(path.stem) > 95:
            continue
        data = json.loads(path.read_text(encoding="utf-8"))
        for word, ficha in data.get("palabras", {}).items():
            seen.setdefault(clean(word).lower(), ficha.get("es", ""))
    for number in range(31, 45):
        path = HERE / f"{number:02d}.txt"
        if not path.exists():
            continue
        for line in path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line.startswith(("W ", "w ")) and " = " in line:
                word, _, gloss = line[2:].partition(" = ")
                seen.setdefault(clean(word).lower(), clean(gloss.split("|")[0]))
    return seen


def source(lesson, number, seen):
    chapter, tr_title, es_title, objective, vocab, phrases, block_type, reading = lesson
    assert len(phrases) == 4, (number, es_title)
    for tr, es in phrases + reading:
        assert 2 <= len(tr.split()) <= 5, (number, tr, len(tr.split()))
        assert tr and es
    lines = ["N " + ", ".join(NAMES),
             f"@ {chapter} | {tr_title} | {es_title}",
             f"I {objective}",
             f"E {es_title} :: {objective} :: {objective}"]
    local = set()
    pending = []
    for word, gloss in vocab:
        key = clean(word).casefold()
        if key not in local:
            if seen.get(key) != gloss:
                lines.append(f"W {word} = {gloss}")
                pending.append(word)
            local.add(key)
            seen.setdefault(key, gloss)
    if pending:
        lines.append("V Vocabulario clave")
    # Las frases breves de cada modelo cuentan como fichas ocultas: al tocar
    # cualquiera de sus palabras, el estudiante obtiene el sentido en contexto.
    for tr, es in phrases + reading:
        phrase = tr.rstrip(" .?!")
        key = clean(phrase).casefold()
        if key not in local:
            gloss = es.rstrip(" .?!")
            if seen.get(key) != gloss:
                lines.append(f"w {phrase} = {gloss}")
            local.add(key)
            seen.setdefault(key, gloss)
    if block_type == "text":
        lines.append("T " + es_title)
        for tr, es in phrases:
            lines.append(f"- {tr} = {es}")
    else:
        lines.append("D " + ("En contexto" if number % 2 else "Una conversación"))
        for i, (tr, es) in enumerate(phrases):
            lines.append(f"{NAMES[(number + i) % len(NAMES)]}: {tr} = {es}")
    if reading:
        lines.append("T " + es_title + " — lectura")
        for tr, es in reading:
            lines.append(f"- {tr} = {es}")
    p = phrases
    q_phrase = reading[0] if reading else p[0]
    q_bad1 = reading[1][1] if len(reading) > 1 else p[1][1]
    q_bad2 = reading[-1][1] if reading else p[2][1]
    # Las seis destrezas de actividad que ya entiende la aplicación. Se alterna
    # el orden para evitar que todas las lecciones se recorran con el mismo ritmo.
    tasks = [
        ("Q", f"¿Qué comunica «{q_phrase[0]}»?", q_phrase[1], q_bad1, q_bad2),
        ("R", f"{p[1][0]} :: Traduce la frase.", p[1][1], p[0][1], p[3][1]),
        ("H", "", "", "", ""),
        ("A", f"{p[3][0]} :: Escucha y elige el sentido.", p[3][1], p[0][1], p[2][1]),
        ("O", f"{p[0][0]} :: {p[0][1]} :: Respeta el orden de palabras del turco.", "", "", ""),
        ("X", f"Escribe en turco: «{p[2][1]}» :: {p[2][0].rstrip(' .?!')} :: Usa la forma del ejemplo.", "", "", ""),
    ]
    order = ["Q", "R", "H", "A", "O", "X"]
    rotations = (number - 1) % len(order)
    order = order[rotations:] + order[:rotations]
    by_type = {task[0]: task for task in tasks}
    for kind in order:
        task = by_type[kind]
        if kind == "Q":
            _, prompt, good, bad1, bad2 = task
            lines += [f"Q {prompt}", f"+ {good} :: Es la información expresada en el modelo.",
                      f"- {bad1} :: Esa idea corresponde a otra frase.",
                      f"- {bad2} :: No es el sentido de la frase preguntada."]
        elif kind == "R":
            _, content, good, bad1, bad2 = task
            phrase, prompt = content.split(" :: ", 1)
            lines += [f"R {phrase} :: {prompt}", f"+ {good} :: Mantiene el sentido de la frase.",
                      f"- {bad1} :: Cambia la información.", f"- {bad2} :: No corresponde a esta expresión."]
        elif kind == "H":
            tr = p[2][0].rstrip(" .?!")
            prefix, answer = tr.rsplit(" ", 1)
            distractors = []
            candidates = [phrase.rstrip(" .?!").split()[-1] for phrase in (p[0][0], p[1][0], p[3][0])]
            candidates.extend(["değil", "daha", "var", "mi"])
            for candidate in candidates:
                if candidate.casefold() not in {answer.casefold(), *(x.casefold() for x in distractors)}:
                    distractors.append(candidate)
                if len(distractors) == 2:
                    break
            lines += [f"H {prefix} ___. :: Completa el modelo.",
                      f"+ {answer} :: Forma la expresión usada en el contexto.",
                      f"- {distractors[0]} :: Pertenece a otra frase.",
                      f"- {distractors[1]} :: No completa este modelo."]
        elif kind == "A":
            _, content, good, bad1, bad2 = task
            phrase, prompt = content.split(" :: ", 1)
            lines += [f"A {phrase} :: {prompt}", f"+ {good} :: Es lo que expresa la frase.",
                      f"- {bad1} :: No coincide con lo que has oído.",
                      f"- {bad2} :: No coincide con lo que has oído."]
        elif kind == "O":
            _, content, _, _, _ = task
            lines.append(f"O {content}")
        elif kind == "X":
            _, content, _, _, _ = task
            lines.append(f"X {content}")
    return "\n".join(lines) + "\n"


def main():
    if len(LESSONS) != 141:
        raise SystemExit(f"El catálogo debe tener 141 lecciones nuevas; tiene {len(LESSONS)}")
    current = 0
    seen = seed_seen()
    for file_index, (chapter, group) in enumerate(groupby(LESSONS, key=lambda x: x[0]), 45):
        records = list(group)
        target = HERE / f"{file_index:02d}.txt"
        parts = ["N " + ", ".join(NAMES)]
        for lesson in records:
            current += 1
            parts.append(source(lesson, current, seen))
        target.write_text("\n".join(parts), encoding="utf-8", newline="\n")
    print(f"{current} lecciones listas en fuentes 45–76.")


if __name__ == "__main__":
    main()
